function applyBackground_color() {
    const colorPicker = document.getElementById('colorPicker');
    const selectedCells = document.querySelectorAll('.background-color, [contenteditable="true"]:focus, .selected-cell');
    let color = colorPicker.value;

    // Clear existing background colors first (optional but good practice)
    document.querySelectorAll('#spreadsheet-container td').forEach(td => {
        td.style.backgroundColor = '';
        td.classList.remove('background-color');
    });

    selectedCells.forEach(cell => {
        cell.style.backgroundColor = color;
        cell.classList.add('background-color');
    });
}
