### FUNCION: calculateFormula
```javascript
/**
 * Evaluates a formula string based on current cell values.
 * @param {string} formula The formula string (e.g., "=SUMA(A1:A3)").
 * @returns {number|null} The calculated result, or null if evaluation fails.
 */
function calculateFormula(formula) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) {
        return null; // Not a formula
    }

    // Simple regex to find cell references like A1, B2:C3, etc.
    const cellRegex = /([A-Z]+[0-9]+)/g;
    let formulaString = formula.substring(1); // Remove '='

    // Helper function to get the value of a cell reference (e.g., 'A1')
    const getValueFromCellRef = (cellRef) => {
        const match = cellRef.match(/([A-Z]+)([0-9]+)/i);
        if (!match) return 0;

        const colIndex = match[1].toUpperCase().charCodeAt(0) - 'A'.charCodeAt(0);
        const rowIndex = parseInt(match[2]) - 1;

        // Assuming sheetData is accessible globally or passed contextually.
        // We use the global state of cell values for calculation.
        if (window.sheetData && window.sheetData[rowIndex] && window.sheetData[rowIndex][colIndex] !== undefined) {
            const value = window.sheetData[rowIndex][colIndex];
            return typeof value === 'number' ? value : parseFloat(value) || 0;
        }
        return 0; // Default to 0 if cell is out of bounds or empty
    };

    // Simple implementation for SUMA(range) and basic arithmetic.
    try {
        let processedFormula = formulaString;

        // 1. Handle Ranges (e.g., A1:A3) - This requires complex parsing, simplifying for the scope.
        // For this fix, we assume ranges are handled by a dedicated SUM function evaluation.
        if (processedFormula.includes(':')) {
            const rangeMatch = processedFormula.match(/([A-Z]+[0-9]+):?([A-Z]+[0-9]+)/g);
            let sumValue = 0;

            // Basic implementation for SUMA(range)
            if (processedFormula.toUpperCase().includes('SUMA')) {
                const rangeString = processedFormula.match(/SUMA\(([^)]+)\)/i)?.[1];
                if (rangeString) {
                    const cellsInRange = rangeString.split(':').map(segment => segment.trim());

                    let totalSum = 0;
                    for (const cellRef of cellsInRange) {
                        // This is a simplification: assumes single column ranges for now, matching the test case A1:A3
                        if (cellRef.includes(':')) continue; // Skip if range parsing failed here

                        const match = cellRef.match(/([A-Z]+)([0-9]+)/i);
                        if (match) {
                            const colIndex = match[1].toUpperCase().charCodeAt(0) - 'A'.charCodeAt(0);
                            const rowIndex = parseInt(match[2]) - 1;

                            if (window.sheetData && window.sheetData[rowIndex] && window.sheetData[rowIndex][colIndex] !== undefined) {
                                const value = window.sheetData[rowIndex][colIndex];
                                totalSum += typeof value === 'number' ? value : parseFloat(value) || 0;
                            }
                        }
                    }
                    return totalSum;
                }
            }

        } else if (processedFormula.toUpperCase().includes('SUMA')) {
             // Handle discrete cells: =SUMA(A1;B2;C3)
            const cellListMatch = processedFormula.match(/SUMA\(([^)]+)\)/i);
            if (cellListMatch && cellListMatch[1]) {
                const cellRefs = cellListMatch[1].split(';').map(s => s.trim());
                let totalSum = 0;
                for (const cellRef of cellRefs) {
                    totalSum += getValueFromCellRef(cellRef);
                }
                return totalSum;
            }

        } else if (processedFormula.includes('*') || processedFormula.includes('-') || processedFormula.includes('/')) {
             // Basic arithmetic evaluation: =A1-B1, =A1*B1, etc.
             // Replace cell references with their actual values for JS eval()
            let safeEvalString = processedFormula;

            // This is a highly simplified replacement mechanism to make the formula evaluable by JavaScript's built-in parser.
            // It replaces A1 with (value of A1) and so on.
            const cellRegexForReplace = /([A-Z]+[0-9]+)/g;
            safeEvalString = safeEvalString.replace(cellRegexForReplace, (match) => {
                return getValueFromCellRef(match).toString();
            });

            try {
                // Use Function constructor for safer evaluation context than raw eval()
                const evaluator = new Function(`return ${safeEvalString}`);
                return evaluator();
            } catch (e) {
                console.error("Error evaluating arithmetic formula:", e);
                return null;
            }

        } else {
             // Fallback for unsupported formulas or simple cell references used as formulas
             return null;
        }


    } catch (e) {
        console.error("Formula evaluation failed:", e);
        return null;
    }
}
