document.addEventListener('DOMContentLoaded', () => {
    // Initialize sheet data structure and event listeners
    window.sheetData = {}; // Global state for cell values (used by formula evaluation)
    const spreadsheetContainer = document.getElementById('spreadsheet-container');

    if (!spreadsheetContainer) return;

    // --- Initialization Logic (Assuming this part is fine) ---
    // ... [Existing initialization code] ...

    // Function to handle setting the value and triggering recalculation
    window.setCellValue = function(rowIndex, colIndex, value) {
        const cellElement = document.getElementById(`cell-${colIndex}-${rowIndex}`);
        if (!cellElement) return;

        let processedValue = String(value).trim();
        let displayValue = processedValue;
        let isFormula = false;

        // 1. Check if the input value is a formula
        if (processedValue.startsWith('=')) {
            isFormula = true;
            const formulaResult = calculateFormula(processedValue);

            if (formulaResult !== null) {
                displayValue = formulaResult.toFixed(2).replace(/\.?0+$/, ''); // Format result
                window.sheetData[rowIndex] = window.sheetData[rowIndex] || {};
                window.sheetData[rowIndex][colIndex] = parseFloat(displayValue); // Store numeric result in data model
            } else {
                // If formula fails to calculate, display the raw formula string (or an error)
                displayValue = processedValue;
                window.sheetData[rowIndex] = window.sheetData[rowIndex] || {};
                window.sheetData[rowIndex][colIndex] = processedValue; // Store formula string in data model
            }

        } else {
            // 2. Handle regular input value
            displayValue = processedValue;
            let numericValue = parseFloat(processedValue);

            if (!isNaN(numericValue)) {
                window.sheetData[rowIndex] = window.sheetData[rowIndex] || {};
                window.sheetData[rowIndex][colIndex] = numericValue; // Store number in data model
            } else {
                 window.sheetData[rowIndex] = window.sheetData[rowIndex] || {};
                 window.sheetData[rowIndex][colIndex] = processedValue; // Store string/text
            }
        }

        // Update the cell display element
        cellElement.textContent = displayValue;

        // 3. Trigger recalculation for dependent cells (Crucial step)
        recalculateDependentCells(rowIndex, colIndex);
    };


    // Function to calculate and update all formulas in a given column/row area
    window.recalculateAllFormulas = function() {
        let needsRecalculation = false;

        for (let r = 0; r < MAX_ROWS; r++) {
            for (let c = 0; c < MAX_COLUMNS; c++) {
                const cellElement = document.getElementById(`cell-${c}-${r}`);
                if (!cellElement) continue;

                // Check if the content is a formula and needs recalculation
                const currentContent = cellElement.textContent.trim();
                if (currentContent.startsWith('=')) {
                    needsRecalculation = true;
                    // Re-run the calculation logic using the stored formula string
                    const formulaString = window.sheetData[r] && window.sheetData[r][c];

                    if (formulaString) {
                        window.setCellValue(r, c, formulaString); // Recalculates and updates display/data model
                    }
                }
            }
        }

        if (needsRecalculation) {
             // After recalculating all formulas, ensure the UI reflects the calculated values
             updateAllCellDisplays();
        }
    };


    // Function to calculate only cells that depend on the changed cell (r, c)
    window.recalculateDependentCells = function(changedRowIndex, changedColIndex) {
        let recalculatedCount = 0;

        for (let r = 0; r < MAX_ROWS; r++) {
            for (let c = 0; c < MAX_COLUMNS; c++) {
                const cellElement = document.getElementById(`cell-${c}-${r}`);
                if (!cellElement) continue;

                // Check if the cell contains a formula and if that formula references the changed cell
                const content = window.sheetData[r] && window.sheetData[r][c];
                if (typeof content === 'string' && content.startsWith('=')) {
                    const formulaString = content;

                    // Simple check: Does the formula string contain a reference to the changed cell?
                    const targetRef = `${window.getColLetter(changedColIndex)}${changedRowIndex + 1}`;
                    if (formulaString.includes(targetRef) || formulaString.includes(`${window.getColLetter(c)}${r + 1}`)) {

                        // Recalculate and update the cell display
                        const result = calculateFormula(formulaString);
                        if (result !== null) {
                            cellElement.textContent = result.toFixed(2).replace(/\.?0+$/, '');
                            recalculatedCount++;
                        }
                    }
                }
            }
        }

        // If any cell was recalculated, ensure the data model reflects the calculated value for future dependency checks
        if (recalculatedCount > 0) {
             updateAllCellDisplays();
        }
    };


    // --- Event Listeners Setup ---

    spreadsheetContainer.addEventListener('input', (e) => {
        const target = e.target;
        if (!target.classList.contains('cell-content')) return;

        let cellElement = target;
        let rowIndex = parseInt(cellElement.dataset.rowIndex);
        let colIndex = parseInt(cellElement.dataset.colIndex);
        let rawValue = cellElement.textContent; // Use current displayed text as input value

        // Update the cell content and trigger recalculations
        window.setCellValue(rowIndex, colIndex, rawValue);
    });


    // Initial calculation run (if any formulas exist on load)
    window.recalculateAllFormulas();
});
