```javascript
document.addEventListener('DOMContentLoaded', () => {
    const spreadsheetContainer = document.getElementById('spreadsheet-container');
    const cells = spreadsheetContainer.querySelectorAll('[contenteditable="true"]');

    // 1. Setup Input Listener for Formula Calculation
    cells.forEach(cell => {
        cell.addEventListener('input', (e) => {
            calculateFormula(e);
        });
    });

    // 2. Setup Event Listeners for Controls
    document.getElementById('btn-clear-data').addEventListener('click', clearSelectedData);
    document.getElementById('colorPicker').addEventListener('change', (e) => {
        // No action needed here, color is applied on button click
    });
    document.getElementById('btn-apply-color').addEventListener('click', applyBackground_color);
    document.getElementById('btn-hide-row').addEventListener('click', () => {
        const selectedRow = getSelectedCell().closest('tr');
        if (selectedRow) {
            hideRow(parseInt(selectedRow.id.split('-')[1]));
        }
    });
    document.getElementById('btn-show-row').addEventListener('click', showAllRows);

    document.getElementById('btn-delete-row').addEventListener('click', () => {
        const selectedCell = getSelectedCell();
        if (selectedCell) {
            const row = selectedCell.closest('tr');
            if (confirm("¿Está seguro de que desea borrar esta fila?")) {
                row.remove();
                // Re-index rows after deletion
                updateRowIndices();
            }
        }
    });

    document.getElementById('btn-clear-column').addEventListener('click', () => {
        const selectedCell = getSelectedCell();
        if (selectedCell) {
            const column = selectedCell.closest('tr');
            // Clear all cells in the same column across all rows
            const columnIndex = Array.from(column.children).indexOf(selectedCell);
            let count = 0;
            document.querySelectorAll('#spreadsheet-container tbody td:nth-child(' + (columnIndex + 1) + ')').forEach(cell => {
                if (!cell.classList.contains('row-index')) { // Skip row index column
                    cell.textContent = '';
                    cell.setAttribute('data-formula', '');
                    cell.removeAttribute('style');
                    count++;
                }
            });
            alert(`Se vaciaron ${count} celdas de la columna.`);
        }
    });

    document.getElementById('btn-hide-col').addEventListener('click', () => {
        const selectedCell = getSelectedCell();
        if (selectedCell) {
            const column = selectedCell.closest('tr');
            // Hide the entire column by hiding all cells in that column across all rows
            column.querySelectorAll('td:not(.row-index)').forEach(cell => {
                cell.classList.add('hidden-column');
            });
        }
    });

    document.getElementById('btn-show-col').addEventListener('click', () => {
        const column = getSelectedCell()?.closest('tr');
        if (column) {
             column.querySelectorAll('td:not(.row-index)').forEach(cell => {
                cell.classList.remove('hidden-column');
            });
        } else {
            // If no cell is selected, show all columns
            document.querySelectorAll('#spreadsheet-container tbody td').forEach(cell => {
                if (!cell.classList.contains('row-index')) {
                    cell.classList.remove('hidden-column');
                }
            });
        }
    });

    // Initial calculation run (in case of pre-filled formulas, though none exist here)
    calculateFormula(null); 
});


/**
 * Obtiene la celda actualmente seleccionada por el usuario.
 * @returns {HTMLElement | null} La celda activa o null si no hay selección.
 */
function getSelectedCell() {
    // Devuelve la celda con foco (active element) dentro del contenedor de datos
    const activeElement = document.activeElement;
    if (activeElement && activeElement.closest('#spreadsheet-container')) {
        return activeElement;
    }
    return null;
}

/**
 * Actualiza los índices de las filas después de una eliminación.
 */
function updateRowIndices() {
    const rows = document.querySelectorAll('#spreadsheet-container tbody tr');
    rows.forEach((row, index) => {
        const rowIndexCell = row.querySelector('.row-index');
        if (rowIndexCell) {
            rowIndexCell.textContent = index + 1;
            row.setAttribute('data-row', index + 1);
        }
    });
}

/**
 * Limpia el contenido de las celdas seleccionadas y elimina cualquier fórmula asociada.
 */
function clearSelectedData() {
    const selectedCell = getSelectedCell();
    if (selectedCell) {
        // Limpiar solo el texto visible, no los atributos data-formula
        selectedCell.textContent = '';
        selectedCell.setAttribute('data-formula', '');
        selectedCell.removeAttribute('style');
        calculateFormula(null); // Recalcular para asegurar que se muestre vacío
    } else {
        alert("Por favor, selecciona una celda con datos o fórmulas.");
    }
}

/**
 * Aplica un color de fondo a las celdas seleccionadas.
 */
function applyBackground_color() {
    const selectedCell = getSelectedCell();
    if (selectedCell) {
        const color = document.getElementById('colorPicker').value;
        selectedCell.style.backgroundColor = color;
        // Nota: Si se aplica un fondo, no debe interferir con el cálculo de fórmulas.
    } else {
        alert("Por favor, selecciona una celda para aplicar el color.");
    }
}

/**
 * Oculta la fila que contiene la celda seleccionada.
 * @param {number} rowIndex El índice de la fila a ocultar (1-based).
 */
function hideRow(rowIndex) {
    const row = document.querySelector(`[data-row="${rowIndex}"]`);
    if (row) {
        row.style.display = 'none';
    }
}

/**
 * Muestra todas las filas de la hoja de cálculo.
 */
function showAllRows() {
    document.querySelectorAll('#spreadsheet-container tbody tr').forEach(row => {
        row.style.display = '';
    });
}


/**
 * Calcula el valor de una fórmula en la celda seleccionada o dada.
 * @param {Event | null} event El evento que disparó el cálculo (útil para saber qué cambió).
 */
function calculateFormula(event) {
    const cell = getSelectedCell();
    if (!cell) return;

    let formulaText = cell.textContent.trim();
    let originalContent = cell.getAttribute('data-original-content') || '';

    // 1. Detectar si el contenido es una fórmula
    if (formulaText && typeof formulaText === 'string' && formulaText.startsWith('=')) {
        const result = evaluateFormula(formulaText);

        if (result !== null) {
            // Mostrar resultado y guardar la fórmula en un atributo para referencia futura
            cell.textContent = result;
            cell.setAttribute('data-formula', formulaText);
            cell.removeAttribute('data-original-content'); // Limpiar contenido original si es fórmula
        } else {
