/**
 * Evalúa una fórmula matemática escrita en formato Excel/Google Sheets.
 * Soporta SUMA(rango), A1-B1, A1*B1, etc.
 * @param {string} formula La cadena de la fórmula (ej: "=SUMA(A1:A3)")
 * @returns {number | null} El resultado numérico o null si falla.
 */
function evaluateFormula(formula) {
    // 1. Limpiar y normalizar la fórmula
    let cleanFormula = formula.toUpperCase().trim();

    if (!cleanFormula.startsWith('=')) return null;
    cleanFormula = cleanFormula.substring(1); // Quitar el '=' inicial

    try {
        // 2. Manejar funciones (SUMA)
        const sumMatch = cleanFormula.match(/SUMA\(([^)]+)\)/i);
        if (sumMatch && sumMatch[1]) {
            const rangeOrCellsString = sumMatch[1];
            let valuesToSum = [];

            // Determinar si es un rango o celdas sueltas
            if (rangeOrCellsString.includes(':')) {
                // Es un rango (A1:A3)
                const [startCellRef, endCellRef] = rangeOrCellsString.split(':');
                let currentRow = parseInt(startCellRef.match(/(\d+)$/) ? startCellRef.match(/(\d+)$/)[1] : '1');
                let currentCol = getColIndexFromLetter(startCellRef.match(/[A-Z]+/)[0]);

                // Iterar sobre el rango de celdas
                for (let r = currentRow; r <= parseInt(endCellRef.match(/(\d+)$/) ? endCellRef.match(/(\d+)$/)[1] : '3'); r++) {
                    for (let c = currentCol; c <= getColIndexFromLetter(endCellRef.match(/[A-Z]+/)[0]); c++) {
                        const cellElement = document.querySelector(`[data-row="${r}"][data-col="A${c}"]`); // Ajustar selector si es necesario
                        if (cellElement) {
                            let value = parseFloat(cellElement.textContent);
                            if (!isNaN(value)) {
                                valuesToSum.push(value);
                            }
                        }
                    }
                }

            } else {
                // Son celdas sueltas (A1;B2;C3)
                const cellRefs = rangeOrCellsString.split(';');
                cellRefs.forEach(ref => {
                    let match = ref.trim().toUpperCase().match(/([A-Z]+)(\d+)/);
                    if (match) {
                        const colLetter = match[1];
                        const rowNum = parseInt(match[2]);

                        // Buscar la celda por su atributo data-row y data-col
                        const cellElement = document.querySelector(`[data-row="${rowNum}"][data-col="${colLetter}"]`);
                        if (cellElement) {
                            let value = parseFloat(cellElement.textContent);
                            if (!isNaN(value)) {
                                valuesToSum.push(value);
                            }
                        }
                    }
                });
            }

            return valuesToSum.reduce((acc, val) => acc + val, 0);
        }

        // 3. Manejar operaciones matemáticas directas (A1-B1, A1*B1, etc.)
        let expression = cleanFormula;

        // Reemplazar referencias de celda (ej: A1) por sus valores numéricos
        expression = expression.replace(/([A-Z]+)(\d+)/g, (match, colLetter, rowNum) => {
            const cellElement = document.querySelector(`[data-row="${rowNum}"][data-col="${colLetter}"]`);
            if (cellElement) {
                let value = parseFloat(cellElement.textContent);
                return isNaN(value) ? '0' : value; // Usar 0 si no es un número válido
            }
            return '0'; // Por defecto, usar 0 si la celda no existe o está vacía
        });

        // Evaluar la expresión matemática resultante (ej: "2+3")
        const result = eval(expression);
        return isNaN(result) ? null : parseFloat(result.toFixed(2));

    } catch (e) {
        console.error("Error al evaluar fórmula:", e);
        return null;
    }
}


