    cellElement.dataset.value = newValue;

    // 2. Check if the input is a formula
    if (newValue && newValue.startsWith('=')) {
        // If it's a formula, we calculate and update the displayed result
        const calculatedValue = calculateFormula(cellElement);
        if (calculatedValue !== null) {
            cellElement.textContent = calculatedValue;
            cellElement.dataset.value = calculatedValue; // Store the resulting number
        } else {
             // If calculation fails, keep the formula visible but mark it as potentially invalid
             cellElement.dataset.value = newValue; 
        }
    } else {
        // If it's a regular value (number or text)
        cellElement.dataset.value = newValue;
    }

    // 3. CRITICAL FIX: After any data change, recalculate all formulas in the sheet
    recalculateAllFormulas();
}
