function recalculateAllFormulas() {
    const cells = document.querySelectorAll('#spreadsheet-container td[contenteditable="true"]');
    let formulasUpdated = false;

    cells.forEach(cell => {
        const formula = cell.dataset.formula;
        if (formula) {
            // Solo intentar calcular si la fórmula está definida y el contenido visible no es ya un resultado numérico/texto
            if (!isNaN(parseFloat(cell.textContent)) && !isFinite(cell.textContent) || cell.textContent === '') {
                try {
                    const result = evaluateFormula(formula, cells);

                    // Si el resultado es diferente al que se muestra actualmente (y no es la fórmula misma), actualizamos.
                    if (result !== null && String(result).trim() !== '' && String(result).trim() !== cell.dataset.formula) {
                        cell.textContent = result;
                        formulasUpdated = true;
                    } else if (result === null || String(result).trim() === '') {
                         // Si el cálculo resulta en vacío o error, lo limpiamos visualmente si no hay fórmula visible
                         if (!isNaN(parseFloat(cell.dataset.formula)) && !isFinite(cell.dataset.formula) || cell.dataset.formula === '') {
                            cell.textContent = '';
                        }
                    }

                } catch (e) {
                    // Manejar errores de cálculo y mostrar el error en la celda si es necesario
                    console.error("Error calculating formula in:", cell);
                    if (cell.dataset.formula && !isNaN(parseFloat(cell.textContent)) && !isFinite(cell.textContent) || cell.textContent === '') {
                        // Si falló, y antes había un valor calculado, lo limpiamos o mostramos el error.
                        cell.textContent = 'Error'; 
                    }
                }
            }
        }
    });

    if (formulasUpdated) {
        console.log("Fórmulas recalculadas exitosamente.");
    } else {
         // console.log("No se detectaron cambios de fórmulas o no fue necesario recalcular.");
    }
}
