```js
/**
 * Global state variables
 */
let selectedRowIndex = null;
let selectedColumnIndex = null;
const MAX_ROWS = 20;
const COLUMNS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];

/**
 * Utility functions
 */

// Función para obtener el valor de una celda específica (fila, columna)
function getCellValue(rowIndex, colName) {
    const cell = document.querySelector(`[data-row="${rowIndex}"][data-col="${colName}"]`);
    return cell ? cell.textContent.trim() : '';
}

// Función para establecer el valor de una celda específica (fila, columna)
function setCellValue(rowIndex, colName, value) {
    const cell = document.querySelector(`[data-row="${rowIndex}"][data-col="${colName}"]`);
    if (cell) {
        cell.textContent = value;
        // Asegurarse de que el contenidoeditable funcione correctamente al escribir
        cell.setAttribute('contenteditable', 'true'); 
    }
}

/**
 * DOM Manipulation and Initialization
 */

function initializeSpreadsheet() {
    const tbody = document.querySelector('#spreadsheet-container table tbody');
    if (!tbody) return;

    // Limpiar contenido existente para recrear la estructura si es necesario
    tbody.innerHTML = ''; 

    for (let i = 1; i <= MAX_ROWS; i++) {
        const row = document.createElement('tr');
        row.setAttribute('data-row', i);

        // Celda de índice de fila
        const indexCell = document.createElement('td');
        indexCell.className = 'row-index';
        indexCell.textContent = i;
        indexCell.setAttribute('data-row', i); // Usar data-row para identificarlo
        row.appendChild(indexCell);

        // Celdas de datos (A a J)
        COLUMNS.forEach((colName, colIndex) => {
            const cell = document.createElement('td');
            cell.setAttribute('data-row', i);
            cell.setAttribute('data-col', colName);
            cell.contentEditable = 'true';
            // Añadir un listener de input para manejar cambios en tiempo real
            cell.addEventListener('input', handleCellInput); 
            row.appendChild(cell);
        });

        tbody.appendChild(row);
    }
}


/**
 * Event Handlers
 */

function setupEventListeners() {
    // Listener para el clic en los índices de fila (el número)
    document.querySelectorAll('.row-index').forEach(header => {
        header.addEventListener('click', handleRowIndexClick);
    });

    // Listener global para la edición de celdas
    const spreadsheetContainer = document.getElementById('spreadsheet-container');
    if (spreadsheetContainer) {
        spreadsheetContainer.addEventListener('input', handleCellInput);
    }


    // Controles de gestión
    document.getElementById('btn-clear-data').addEventListener('click', clearSelectedData);
    document.getElementById('colorPicker').addEventListener('change', (e) => { 
        // Solo actualizamos el valor, la aplicación ocurre al hacer clic en Aplicar Color
    });
    document.getElementById('btn-apply-color').addEventListener('click', applyBackground_color);
    document.getElementById('btn-delete-row').addEventListener('click', deleteSelectedRow);
    document.getElementById('btn-clear-column').addEventListener('click', clearSelectedColumn);
    document.getElementById('btn-hide-col').addEventListener('click', hideSelectedColumn);
    document.getElementById('btn-show-col').addEventListener('click', showSelectedColumn);

    // Listener para el clic en cualquier parte de la hoja (para seleccionar celdas)
    const spreadsheetBody = document.querySelector('#spreadsheet-container table tbody');
    if (spreadsheetBody) {
        spreadsheetBody.addEventListener('click', handleCellClick);
    }
}


/**
 * Core Logic Functions
 */

// Maneja el input de texto en cualquier celda editable
function handleCellInput(event) {
    const target = event.target;
    if (target.tagName !== 'TD' || !target.hasAttribute('data-row') || !target.hasAttribute('data-col')) return;

    // Si se está editando una celda, actualizamos el estado de selección si es necesario
    const row = target.closest('tr');
    if (row) {
        // Esto podría ser usado para actualizar la lógica de botones o estados
    }
}


/**
 * SELECCIÓN Y MANIPULACIÓN DE FILAS/COLUMNAS
 */

function getSelectedRow() {
    const selectedElement = document.querySelector('.selected');
    if (!selectedElement) return null;
    return parseInt(selectedElement.getAttribute('data-row'));
}

function getSelectedColumn() {
    // Asume que la columna seleccionada es la más a la derecha de la fila seleccionada, o se debe pasar explícitamente.
    // Para simplificar, si solo hay una selección activa (por el click en el índice), asumimos que no está seleccionado nada específico aún.
    return null; 
}

function updateControlsState() {
    const selectedRow = getSelectedRow();
    const isRowSelected = !!selectedRow;

    // Habilitar/Deshabilitar botones de fila
    document.getElementById('btn-delete-row').disabled = !isRowSelected;
    document.getElementById('btn-hide-row').disabled = !isRowSelected;

    // Mostrar/Ocultar botón de mostrar fila si no hay selección o si es necesario (lógica compleja, se mantiene simple)
    const showRowBtn = document.getElementById('btn-show-row');
    if (showRowBtn) {
