/**
 * Actualiza el estado de los botones de control (habilitar/deshabilitar) 
 * basándose en si hay una fila seleccionada o no.
 * @param {string|number|null} rowIndex - El índice de la fila seleccionado, o null si ninguna.
 */
function updateControlsForRow(rowIndex) {
    const isRowSelected = !!rowIndex;

    // Controles de Fila (Borrar/Ocultar/Mostrar)
    document.getElementById('btn-delete-row').disabled = !isRowSelected;
    document.getElementById('btn-hide-row').disabled = !isRowSelected;
    document.getElementById('btn-show-row').style.display = isRowSelected ? 'inline-block' : 'none';

    // Controles de Columna (Borrar/Ocultar/Mostrar) - Estos son globales, pero se mantienen por si acaso
    // Si la lógica requiere que estos botones estén siempre disponibles o deshabilitados globalmente, 
    // esta parte podría ajustarse. Por ahora, los dejamos como estaban en el original.

    // Control de datos (Vaciar Datos Seleccionados) - Siempre disponible si hay celdas seleccionables
    const selectedCells = document.querySelectorAll('.selected td[contenteditable="true"]');
    document.getElementById('btn-clear-data').disabled = selectedCells.length === 0;

    // Control de color (Aplicar Color) - Depende de la selección
    document.getElementById('btn-apply-color').disabled = selectedCells.length === 0;
}


/**
