 * Selecciona visualmente la fila y actualiza los controles.
 * @param {Event} event - El evento de clic.
 */
function handleRowIndexClick(event) {
    const clickedCell = event.currentTarget;
    // Obtener el índice de la fila (el número visible en la celda)
    const rowIndex = clickedCell.textContent.trim();

    if (!rowIndex || isNaN(parseInt(rowIndex))) return;

    // 1. Deseleccionar todas las filas primero
    document.querySelectorAll('.row-index').forEach(cell => {
        cell.parentElement.classList.remove('selected');
    });

    // 2. Seleccionar la fila actual (sin ocultarla)
    const row = clickedCell.closest('tr');
    if (row) {
        row.classList.add('selected');
        // Actualizar el estado de los botones de control para esta fila
        updateControlsForRow(parseInt(rowIndex));
    }

    // 3. Enfocar la celda seleccionada para mejorar la UX
    clickedCell.focus();
}


