### FUNCION: deleteColumn
```js
function deleteColumn(colIndex) {
    // colIndex es el número de columna a eliminar (1-based).

    if (colIndex < 1 || isNaN(colIndex)) {
        alert("Por favor, ingrese un número de columna válido.");
        return;
    }

    const tableBody = document.querySelector('tbody');
    const rows = tableBody.querySelectorAll('tr');

    // Iterar sobre todas las filas y eliminar el N-ésimo hijo (columna)
    rows.forEach(row => {
        const cells = row.querySelectorAll('td');
        if (cells[colIndex - 1]) {
            cells[colIndex - 1].remove();
        }
    });

    // Eliminar la cabecera de la columna en thead
    const headerCells = document.querySelector('thead th');
    if (headerCells) {
        headerCells.remove(colIndex - 1);
    }

    console.log(`Columna ${colIndex} eliminada exitosamente.`);
}
