function updateRowIndices() {
    const rows = document.querySelectorAll('tbody tr');
    let index = 1;
    rows.forEach(row => {
        // Encontrar o crear el elemento de índice (el primer <th> dentro del <tr>)
        let indexCell = row.querySelector('.row-index');

        if (!indexCell) {
            // Si por alguna razón no existe, lo creamos y lo añadimos al inicio de la fila
            indexCell = document.createElement('th');
            indexCell.className = 'row-index';
            indexCell.style.width = '50px'; // Asegurar el ancho correcto
            row.prepend(indexCell); 
        }

        // Actualizar el contenido del índice
        indexCell.textContent = index;
        index++;
    });
}
