### FUNCION: getColumnLetterFromIndex
```javascript
function getColumnLetterFromIndex(index) {
    let letter = '';
    while (index >= 0) {
        letter = String.fromCharCode((index % 26) + 65) + letter;
        index = Math.floor(index / 26) - 1;
    }
    return letter;
}
