        const target = e.target;
        if (target.closest('[contenteditable="true"]')) {
            // Si se hace clic en una celda editable, simplemente seleccionarla y no hacer nada más.
            // Esto evita que el click active accidentalmente la lógica de row-index o col-header.
            return;
