### FUNCION: loadDataFromLocalStorage
```js
function loadDataFromLocalStorage() {
    const cells = document.querySelectorAll('[contenteditable="true"]');
    cells.forEach(cell => {
        const row = cell.dataset.row;
        const col = cell.dataset.col;
        const key = `${col}${row}`;
        const savedValue = localStorage.getItem(key);

        if (savedValue !== null) {
            // Set the content, ensuring it handles potential HTML tags if they were stored that way, 
            // but since we are dealing with text input, setting innerHTML or textContent is fine.
            cell.textContent = savedValue;
        } else {
             // Ensure cells start clean if no data is found
             cell.textContent = '';
        }
    });
}
```

