```js
function saveDataToLocalStorage(event) {
    const cell = event.target;
    if (cell && cell.dataset.row && cell.dataset.col) {
        const row = cell.dataset.row;
        const col = cell.dataset.col;
        const key = `${col}${row}`;
        localStorage.setItem(key, cell.textContent);
    }
}
