function evaluateFormula(formulaString) {
    if (!formulaString || !formulaString.startsWith('=')) {
        return formulaString;
    }

    // Simple regex to find cell references like A1, B2, etc., and extract coordinates
    const cellRegex = /([A-Z]+[0-9]+)/g;
    let formula = formulaString.substring(1).toUpperCase(); // Remove '=' and make uppercase

    // Replace cell references with their actual values in the current spreadsheet state
    formula = formula.replace(cellRegex, (match) => {
        const matchCell = document.querySelector(`[data-row="${match.substring(1)}"][data-col="${match.charAt(0)}"]`);
        if (matchCell && matchCell.textContent !== undefined) {
            let value = matchCell.textContent.trim();
            // Check if the cell content is numeric, otherwise treat it as 0 for calculation purposes
            return isNaN(parseFloat(value)) ? '0' : value;
        }
        return '0'; // Default to 0 if cell not found or empty
    });

    try {
        // Use Function constructor for safe evaluation of mathematical expressions
        // This handles basic arithmetic and functions like SUMA (which we map to Math.sum/reduce)
        let expression = formula;

        // Basic handling for SUMA(X;Y) -> X + Y
        if (expression.includes('SUMA')) {
            const sumMatch = expression.match(/SUMA\(([^)]+)\)/i);
            if (sumMatch) {
                let argsString = sumMatch[1].replace(/;/g, ',').trim(); // Replace semicolon with comma for JS array/function compatibility
                // Split arguments by comma and evaluate them individually
                const values = argsString.split(',').map(arg => arg.trim());

                if (values.length > 0) {
                    let sum = 0;
                    for (const val of values) {
                        sum += parseFloat(val);
                    }
                    return sum.toString();
                }
            }
        }

        // Attempt to evaluate the resulting expression string as a mathematical calculation
        // Note: This is still limited but handles basic arithmetic operations after substitution.
        const result = new Function('return ' + expression)();
        return (typeof result === 'number' && !isNaN(result)) ? result.toFixed(2).replace(/\.?0+$/, '') : String(result);

    } catch (e) {
        // If evaluation fails, return the original formula string
        console.error("Formula evaluation failed:", e);
        return formulaString;
    }
}
