function evaluateFormula(formulaString) {
    if (!formulaString || typeof formulaString !== 'string' || !formulaString.startsWith('=')) {
        return formulaString; // Not a formula or empty
    }

    // Simple parsing for =SUMA(A1;B1) format
    try {
        const content = formulaString.substring(1).trim(); // Remove '='
        if (!content.startsWith('SUMA')) return formulaString;

        // Extract arguments: A1;B1 -> ["A1", "B1"]
        const argsString = content.substring(4).trim(); // Skip SUMA
        if (!argsString) return formulaString;

        const cellReferences = argsString.split(';').map(ref => ref.trim());

        let sum = 0;
        for (const ref of cellReferences) {
            // Assuming A1 format: ColumnLetter + RowNumber
            const colChar = ref.match(/[A-Z]+/)[0];
            const rowNum = parseInt(ref.match(/\d+/)[0]);

            if (!colChar || isNaN(rowNum)) continue;

            // Calculate index (assuming A=1, B=2...)
            let colIndex = 0;
            for (let i = 0; i < colChar.length; i++) {
                colIndex = colIndex * 26 + (colChar.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
            }

            // Get the cell element and its value from the spreadsheet container
            const cellElement = document.querySelector(`[data-row="${rowNum}"][data-col="${colIndex}"]`);
            if (cellElement && cellElement.dataset.value !== undefined) {
                let value = parseFloat(cellElement.dataset.value);
                if (!isNaN(value)) {
                    sum += value;
                }
            }
        }

        // Return the calculated sum formatted as a string
        return sum.toString();

    } catch (e) {
        console.error("Error evaluating formula:", e);
        return formulaString; // Fallback to displaying raw formula if error occurs
    }
}
