    // Remove the structural elements (header, data cells)
    const columnIndex = parseInt(colHeaderElement.dataset.colIndex);

    // Remove header element
    colHeaderElement.remove();

    // Remove all corresponding data column structures
    document.querySelectorAll(`.col-data[data-col-index="${columnIndex}"]`).forEach(el => el.remove());


    // 3. Update indices and re-render/recalculate everything
    updateColumnIndices(); // Updates dataset attributes for remaining columns
    updateRowIndices();   // Re-runs row index updates

    // Since we deleted a column, all subsequent columns shift left by one.
    // We must ensure the visual layout reflects this immediately.
    applyBackground_color(); 
}


/**
 * Updates the dataset attributes for all remaining columns to reflect their new indices.
 */
function updateColumnIndices() {
    const container = document.getElementById('spreadsheet-container');
    if (!container) return;

    // Update column headers
    document.querySelectorAll('.col-header').forEach(header => {
        const newIndex = parseInt(header.dataset.colIndex);
        header.dataset.colIndex = newIndex; // Reconfirming the index
        header.textContent = getColumnLetterFromIndex(newIndex);
    });

    // Update data cells
    document.querySelectorAll('.data-cell').forEach(cell => {
        const oldIndex = parseInt(cell.dataset.colIndex);
        if (oldIndex >= parseInt(document.querySelector(`.col-header[data-col-index="${parseInt(colIndex)}"]`))?.dataset.colIndex || 0) {
             // If the cell was in a column that was deleted, it should already be removed.
             // For remaining cells, we just ensure the index is correct relative to its new position.
        }
        const newColIndex = parseInt(cell.parentElement.dataset.colIndex); // Assuming parent handles current col index
        cell.dataset.colIndex = newColIndex; 
    });

    // Re-apply background colors or structural adjustments if needed
    applyBackground_color();
}


