        } else {
            cell.classList.remove('background-color');
        }
    });
}

/**
 * Recalculates the value of a cell based on its content (e.g., formulas).
 * @param {HTMLElement} cell - The cell element to recalculate.
 */
function recalculateCell(cell) {
    // Placeholder for complex calculation logic (e.g., checking if content starts with '=')
    if (cell.textContent.trim().startsWith('=')) {
        try {
            const formula = cell.textContent;
            // Simple evaluation: assumes formulas only reference other cells in the DOM
            let result = eval(formula); 
            cell.textContent = result;
        } catch (e) {
            console.error("Error calculating formula:", e);
            cell.textContent = "ERROR";
