function hideRow(rowIndex) {
    const rowElement = document.querySelector(`tr[data-row="${rowIndex}"]`);
    if (rowElement) {
        // Usamos la clase CSS dedicada para ocultar toda la fila, incluyendo el índice de fila.
        rowElement.classList.add('hidden-row'); 
        // Actualizar índices después de ocultar una fila
        updateRowIndices();
    }
}
```
